import {createRepairUI} from './repair-ui.mjs';
import {createExamHistory,examScore,examMastery} from './exam-history.mjs';
import {buildComparison} from './comparison-model.mjs';
import {predictionEvents} from './prediction-model.mjs';
export function examProfile(history){const recent=history.slice(-3),mean=recent.length?recent.reduce((n,e)=>n+examScore(e),0)/recent.length:0,tier=recent.length>=3&&mean>=85?'advanced':recent.length>=2&&mean>=70?'intermediate':'foundation',errors={};for(const e of recent)for(const [i,q]of e.questions.entries())if(e.answers[i]!==q.answer.id)errors[q.answer.id]=(errors[q.answer.id]||0)+1;return {tier,mean,count:recent.length,errors};}
export function makeExam(random=Math.random,history=[]){const profile=examProfile(history),shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};const kinds=profile.tier==='advanced'?['sensor','pressureWave','combined']:profile.tier==='intermediate'?['jam','sensor','pressureWave']:['pressure','jam','sensor'],questions=[];for(const kind of kinds){const model=buildComparison(kind),events=predictionEvents(model),catalog=[...new Map(events.flatMap(e=>e.options).map(o=>[o.id,o])).values()],pool=[];for(const e of events.filter(e=>e.index>=model.first&&(kind==='combined'||kind==='pressureWave'||e.index<=model.alarm))){const changes=e.changes.filter(c=>c.bank==='fault');for(const answer of changes){const distractors=catalog.filter(o=>!changes.some(c=>c.id===o.id)).slice(0,3);pool.push({...e,bank:'fault',answer,options:shuffle([{id:answer.id,label:answer.label,type:answer.type},...distractors])});}}const chosen=[],ranked=shuffle(pool).sort((a,b)=>(profile.errors[b.answer.id]||0)-(profile.errors[a.answer.id]||0));if(kind==='combined'){for(const id of ['ps','i0']){const q=ranked.find(e=>e.answer.id===id);if(q)chosen.push(q);}}for(const e of ranked)if(!chosen.some(q=>q.answer.id===e.answer.id)&&chosen.length<2)chosen.push(e);questions.push(...chosen.map(e=>({...e,kind})));}return {id:crypto.randomUUID(),date:new Date().toISOString(),questions:shuffle(questions),answers:[],status:'active',tier:profile.tier,adaptation:profile};}
export function examRecords(exam){return exam.answers.map((id,i)=>{const e=exam.questions[i],correct=id===e.answer.id;return {id:exam.id+':'+i,date:exam.date,completedAt:exam.finishedAt,kind:e.kind,signal:e.answer.id,label:e.answer.label,resolved:true,points:correct?100:0,errors:correct?0:1,hints:0,revealed:false,wrong:correct?[]:[e.options.find(o=>o.id===id)?.label||'Sin respuesta'],review:true,level:'exam',exam:true,correct};});}
export function createWeeklyExam(host,{storage,ready,loadExperiment,seek,refresh,save,onSaved,startExact,displayPair}){let inspected=null;const archive=createExamHistory(storage);let exam=null,open=false,warning='';const key='mecanica.weekly-exam.v1';try{const saved=JSON.parse(storage.getItem(key)||'null');if(saved&&Array.isArray(saved.questions)&&saved.questions.length===6&&Array.isArray(saved.answers)&&saved.answers.length<=6&&['active','finished','abandoned'].includes(saved.status)&&saved.questions.every(e=>['pressure','jam','sensor','pressureWave','combined'].includes(e.kind)&&Number.isInteger(e.index)&&e.answer&&Array.isArray(e.options)))exam=saved;}catch{warning='No se pudo recuperar el examen local.';}
 if(exam?.status==='finished')archive.add(exam);
 const repair=createRepairUI({displayPair,refresh});
 const persist=()=>{try{storage.setItem(key,JSON.stringify(exam));}catch{warning='El examen solo se conserva en esta sesión.';}};
 const view=(e,after=false)=>{loadExperiment(e.kind);seek(e.index-(after?0:1));};
 function finish(){exam.status='finished';exam.finishedAt=new Date().toISOString();examRecords(exam).forEach(save);archive.add(exam);persist();onSaved();refresh();}
 function render(){const focusId=host.contains(document.activeElement)?document.activeElement.id:null;host.replaceChildren();if(repair.active()){repair.render(host,()=>view((inspected||exam).questions[0],true));if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});return;}const el=(tag,text,parent=host)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};el('h2','Examen semanal · casos sorpresa');el('p','6 predicciones de tres escenarios simulados. Una respuesta por pregunta, sin pistas ni corrección hasta terminar. Es práctica libre: puedes repetir. Al finalizar, cada acierto vale 100 y cada error 0; la nota es la media. Los errores ajustan tus repasos y no cuentan para la meta diaria.');if(warning)el('p',warning);if(archive.warning())el('p',archive.warning());
 if(!open){const profile=examProfile(archive.all());el('p','Próximo nivel: '+({foundation:'Fundamentos',intermediate:'Intermitencias',advanced:'Combinados'}[profile.tier])+'. Se priorizan señales falladas en los últimos tres exámenes. Con dos exámenes y media ≥70 se añaden intermitencias; con tres y media ≥85 se combinan averías. Si baja la media, vuelve el apoyo.');renderHistory(el);const b=el('button',exam?.status==='active'?'Continuar examen pendiente':'Comenzar examen sorpresa');b.id='examStart';b.disabled=!ready();b.onclick=()=>{if(exam?.status!=='active'){exam=makeExam(Math.random,archive.all());persist();}open=true;if(exam.answers.length===6)finish();else view(exam.questions[exam.answers.length]);};if(exam?.status==='finished'){const b=el('button','Revisar último examen');b.onclick=()=>{open=true;refresh();};}return;}
 const exit=el('button',!inspected&&exam.status==='active'?'Guardar y salir':'Cerrar revisión');exit.id='examExit';exit.onclick=()=>{open=false;inspected=null;persist();refresh();};
 if(!inspected&&exam.status==='active'){const n=exam.answers.length,e=exam.questions[n];el('h3','Pregunta '+(n+1)+' / 6 · banco '+(e.bank==='fault'?'averiado':'normal'));el('p','Observa el scan anterior. ¿Qué señal cambiará a los '+(e.index*.02).toFixed(2)+' s?');const choices=el('div','');choices.id='examChoices';choices.className='actions';for(const o of e.options){const b=el('button',o.label,choices);b.onclick=()=>{if(exam.status!=='active'||exam.answers.length!==n)return;exam.answers.push(o.id);persist();if(exam.answers.length===6)finish();else view(exam.questions[exam.answers.length]);};}return;}
 const shown=inspected||exam;const records=examRecords(shown),score=Math.round(records.reduce((n,r)=>n+r.points,0)/6);el('h3','Resultado: '+score+'/100 · '+records.filter(r=>r.correct).length+' / 6 aciertos');el('p','Resultados guardados. Tus errores ya alimentan las dificultades, los intervalos y el plan semanal. Revisa antes/después para relacionar entrada, contacto y salida.');
 el('h3','Repara los casos del examen');el('p','Elige un caso para intervenir en el circuito, rearmar y verificar un ciclo completo. Puntuación independiente, disponible durante esta práctica.');for(const kind of new Set(shown.questions.map(e=>e.kind))){const b=el('button','Reparar · '+({pressure:'presión baja',jam:'atasco de A',sensor:'sensor a1 intermitente',pressureWave:'presión fluctuante',combined:'presión + sensor a0'}[kind]));b.dataset.repairKind=kind;b.disabled=!ready();b.onclick=()=>repair.start(kind);}
 const failed=shown.questions.map((e,i)=>({...e,sourceExam:shown.id,sourceQuestion:i})).filter((e,i)=>!records[i].correct);if(failed.length){const b=el('button','Repetir los '+failed.length+' retos fallados');b.id='examRetryFailed';b.disabled=!ready();b.onclick=()=>retry(failed);}
 for(const [i,e]of shown.questions.entries()){const r=records[i],card=el('article','');card.className='exam-review';el('h4',(i+1)+' · '+(r.correct?'Correcto':'Para repasar')+' · '+e.answer.label,card);el('p','Elegiste: '+(e.options.find(o=>o.id===shown.answers[i])?.label||'—')+(r.correct?'. ':'. Esa opción no cambia en este scan. ')+'Cambia: '+e.answer.label+' '+e.answer.from+' → '+e.answer.to+'.',card);el('p',({pressureWave:'La presión oscila entre 2 y 6 bar. PS cruza el umbral de 3 bar, pero el fallo queda retenido aunque vuelva la presión.',combined:'Hay dos fallos: presión ausente temporalmente y sensor a0 intermitente. Al volver el aire, A regresa; a0 alterna aun estando en origen. Recuperar presión no borra FALLO.',pressure:'La presión cae: PS=0 activa P01; el PLC retira las salidas. Sin presión el pistón no se mueve.',jam:'El atasco inmoviliza A aunque haya orden. Sin a1, la supervisión termina disparando timeout.',sensor:'a1 pierde señal por momentos aun con A en el extremo. El TON se reinicia y la falta de confirmación puede disparar timeout.'})[e.kind],card);el('p','En este scan: '+e.changes.map(c=>(c.bank==='fault'?'Averiado':'Normal')+' '+c.label+' '+c.from+'→'+c.to).join(' · '),card);for(const [label,after]of [['Ver antes',false],['Ver cambio',true]]){const b=el('button',label,card);b.disabled=!ready();b.onclick=()=>view(e,after);}if(!r.correct){const b=el('button','Volver a predecir este reto',card);b.disabled=!ready();b.onclick=()=>retry([{...e,sourceExam:shown.id,sourceQuestion:i}]);}}
 }

 function retry(events){open=false;inspected=null;startExact(structuredClone(events));}
 function renderHistory(el){const exams=archive.all();el('h3','Historial de exámenes');el('p','Últimos 50 exámenes completos en este navegador. Los repasos no sustituyen la nota original. Se recupera el último examen guardado por la versión anterior; los exámenes antiguos sobrescritos no pueden reconstruirse.');if(!exams.length){el('p','Completa un examen para comenzar la comparación.');return;}const graph=el('div','');graph.className='exam-scores';for(const e of exams.slice(-10)){const line=el('div','',graph);el('span',new Date(e.finishedAt).toLocaleDateString('es-CO'),line);const meter=el('meter','',line);meter.max=100;meter.value=examScore(e);meter.setAttribute('aria-label','Nota de examen: '+examScore(e));el('strong',examScore(e)+'/100',line);}const list=el('div','');list.className='exam-archive';for(const [i,e]of [...exams].reverse().entries()){const row=el('article','',list),score=examScore(e),originalIndex=exams.length-1-i,previous=exams[originalIndex-1];el('strong',new Date(e.finishedAt).toLocaleString('es-CO')+' · '+score+'/100 · '+e.answers.filter((a,j)=>a!==e.questions[j].answer.id).length+' errores',row);el('p',previous?'Cambio frente al anterior: '+(score-examScore(previous)>0?'+':'')+(score-examScore(previous))+' puntos.':'Primer examen guardado.',row);const b=el('button','Revisar examen',row);b.disabled=!ready();b.onclick=()=>{inspected=e;open=true;refresh();};}el('h3','Qué señales vas consolidando');el('p','Últimas cinco respuestas de examen por señal. Se requieren al menos tres respuestas repartidas en tres exámenes para indicar consistencia. Los casos aleatorios pueden variar; las notas no son pruebas equivalentes y los repasos se registran aparte.');for(const s of examMastery(exams))el('p',s.label+' · '+s.correct+'/'+s.n+' recientes correctas · '+s.errors+' errores acumulados · '+s.status);}
 return {render,active:()=>open,testing:()=>open&&!inspected&&exam?.status==='active',state:()=>exam};
}
